// Names an incoming RPC back to the `fin` command it stands for (sub-project 7B Decision 2,
// spec §7.2), through the exported registry (`packages/contracts/registry.json`, generated by
// `fin schema --registry`). Command rules are matched against these names, so a rule on
// `render` or `plugin.install` holds whether the call came from `fin`, a hand-written client or
// the built-in tool. Also the journal's argv-level naming of a `fin` tool call.
//
// The contract with policy: a caller shapes the payload, so it can make one RPC look like
// several commands (pad an `asset.add` transaction with other ops, send `name` with
// `archived`). Policy must therefore evaluate EVERY name `commandsOf` returns and take the
// strictest verdict (deny beats ask beats allow): an extra name can only tighten, never loosen.
// `commandOf` (the first name) is for display and the journal only, never for a decision. The
// last name is always `rpc:<method>`, so a rule can name any RPC. A plugin command's name comes
// only from the host (`trusted.via`), never from the payload.
import type { FinRpcTag } from "@finisher/contracts";
import { REGISTRY, type RegistryMatch } from "@finisher/contracts/registry";

/**
 * RPCs no `fin` command names: helpers the commands call for themselves (a snapshot, a probe, a
 * plan), the handshake and credentials, streams, the library and training stores, and the agent
 * runtime's own. Rules still name them as `rpc:<method>`. `every_rpc_is_named_or_rpc_only`
 * fails when a new RPC is in neither this set nor a command's row (`registry_rpcs*.rs`).
 */
export const RPC_ONLY: ReadonlySet<FinRpcTag> = new Set<FinRpcTag>([
  // The handshake, credentials, the console and the server's own state.
  "server.hello",
  "server.status",
  "server.stop",
  "auth.prove",
  "auth.ticket",
  "auth.whoami",
  "auth.revokeSelf",
  "auth.audit.list",
  "auth.audit.purge",
  "auth.credential.mint",
  "auth.credential.list",
  "auth.credential.revoke",
  "auth.credential.rotateMaster",
  "console.challenge",
  // Helpers and streams of the project commands.
  "asset.probe",
  "tx.get",
  // Every edit command fetches a snapshot for its base, so `view` names no RPC.
  "snapshot.get",
  "fonts.plan",
  "plugin.content.get",
  "plugin.discard",
  "ops.subscribe",
  "project.events",
  "diagnostics.record",
  // Jobs are submitted by the server's own features; a `render` job is named `render`
  // (`SERVER_NAMED`) until a `fin` render command arrives with its row.
  "jobs.submit",
  "jobs.watch",
  "jobs.workers",
  // The library's person-only and internal RPCs (the `fin library` ones are its commands'), and
  // the training store.
  "library.add",
  "library.remove",
  "library.lookup",
  "library.watch",
  "training.closedTargets.get",
  "training.closedTargets.set",
  // The agent runtime (plan 7A), reached through `fin agent` and the console.
  "agent.session.start",
  "agent.session.prompt",
  "agent.session.steer",
  "agent.session.interrupt",
  "agent.session.resume",
  "agent.session.end",
  "agent.session.list",
  "agent.session.get",
  "agent.session.delete",
  "agent.watch",
  "agent.approval.answer",
  "agent.providers",
  "agent.self",
  "agent.self.try",
  "agent.rules.list",
  "agent.rules.add",
  "agent.rules.remove",
  "agent.project.trust",
  "agent.key.set",
  "agent.key.list",
  "agent.key.remove",
  "agent.local.set",
  "agent.local.show",
  "agent.local.test",
  "agent.local.remove",
  // 5B: pairing, devices, the environment and settings, reached through the console and apps.
  "auth.pair.offer",
  "auth.pair.approve",
  "auth.pair.reject",
  "auth.pair.pending",
  "auth.device.list",
  "auth.device.rename",
  "auth.device.revoke",
  "auth.devices.watch",
  "env.describe",
  "env.name",
  "env.adopt",
  "env.reset",
  "env.rotateIdentity",
  "settings.write",
]);

type Condition = readonly [path: string, expect: RegistryMatch];
interface Candidate {
  readonly name: string;
  readonly conditions: readonly Condition[];
}

/** What only the host knows about a call: the plugin that committed it (sp8 §3.8), if any. */
export interface TrustedContext {
  readonly via?: { readonly plugin: string; readonly command: string };
}

/** method → the registry's commands sending it, in registry order (one per RPC entry). */
const BY_METHOD: ReadonlyMap<string, readonly Candidate[]> = (() => {
  const index = new Map<string, Candidate[]>();
  for (const c of REGISTRY.commands) {
    if (c.dynamic === true) continue;
    for (const rpc of c.rpcs) {
      const list = index.get(rpc.method) ?? [];
      list.push({ name: c.name, conditions: Object.entries(rpc.match ?? {}) });
      index.set(rpc.method, list);
    }
  }
  return index;
})();

/**
 * Names the server gives RPCs no registry row covers yet. `jobs.submit` of a `render` job is
 * `render` until a `fin` render command exists; its registry row then replaces this entry.
 */
const SERVER_NAMED: Readonly<Record<string, readonly Candidate[]>> = {
  "jobs.submit": [{ name: "render", conditions: [["kind", "render"]] }],
};

/** The values at a dotted path (`*` stands for every element of an array); none for a miss or a `null`. */
function valuesAt(value: unknown, path: readonly string[]): unknown[] {
  const [head, ...rest] = path;
  if (head === undefined) return value === undefined || value === null ? [] : [value];
  if (head === "*") return Array.isArray(value) ? value.flatMap((v) => valuesAt(v, rest)) : [];
  if (typeof value !== "object" || value === null || Array.isArray(value)) return [];
  return valuesAt((value as Record<string, unknown>)[head], rest);
}

function holds(payload: unknown, [path, expect]: Condition): boolean {
  const found = valuesAt(payload, path.split("."));
  if (typeof expect === "object") return expect.present ? found.length > 0 : found.length === 0;
  return found.some((v) => v === expect);
}

/** `plugin:<id>/<command>` of a transaction the plugin host says a plugin committed. */
function pluginCommand(trusted: TrustedContext | undefined): string | undefined {
  const via = trusted?.via;
  if (via === undefined || via.plugin === "") return undefined;
  const at = via.plugin.lastIndexOf("@");
  const id = at > 0 ? via.plugin.slice(0, at) : via.plugin;
  return `plugin:${id}/${via.command}`;
}

/** Whether a `tx.commit` holds more than one op. */
function severalOps(payload: unknown): boolean {
  const [ops] = valuesAt(payload, ["tx", "ops"]);
  return Array.isArray(ops) && ops.length > 1;
}

/**
 * Every command an RPC could be, most specific first (the most conditions, then registry
 * order), ending with `rpc:<method>`. A command with no condition (`batch`) is named when no
 * conditioned one matches, and for any transaction of several ops. Several commands share an
 * RPC and its conditions when the wire cannot tell them apart (`item.trim` and `clip.trim`
 * commit the same op): policy checks all of them (see the contract above). `trusted` is what
 * the host, not the payload, says about the call.
 */
export function commandsOf(method: string, payload: unknown, trusted?: TrustedContext): string[] {
  const plugin = method === "tx.commit" ? pluginCommand(trusted) : undefined;
  const all = [...(BY_METHOD.get(method) ?? []), ...(SERVER_NAMED[method] ?? [])];
  const candidates = all.filter((c) => c.conditions.every((cond) => holds(payload, cond)));
  const specific = candidates.filter((c) => c.conditions.length > 0).sort((a, b) => b.conditions.length - a.conditions.length);
  const plain = candidates.filter((c) => c.conditions.length === 0);
  const general = specific.length === 0 || (method === "tx.commit" && severalOps(payload)) ? plain : [];
  const names = [...(plugin === undefined ? [] : [plugin]), ...specific.map((c) => c.name), ...general.map((c) => c.name)];
  return [...new Set([...names, `rpc:${method}`])];
}

/** The command an RPC stands for, for display and the journal: the first of [`commandsOf`]. */
export function commandOf(method: FinRpcTag | (string & {}), payload: unknown, trusted?: TrustedContext): string {
  return commandsOf(method, payload, trusted)[0] as string;
}

/** The `fin` command of an argv (`["item", "trim", "c1"]` → `item.trim`); the journal maps unknown ones to `other`. */
export function commandOfArgv(input: unknown): string | undefined {
  const argv = (input as { argv?: unknown } | null)?.argv;
  if (!Array.isArray(argv)) return undefined;
  const words: string[] = [];
  for (const a of argv) {
    if (typeof a !== "string" || a.startsWith("-") || !/^[a-z][a-zA-Z0-9-]*$/.test(a) || words.length === 2) break;
    words.push(a);
  }
  return words.length === 0 ? undefined : words.join(".");
}
